{
  "name": "opencode-telegram-monitor",
  "version": "1.0.0",
  "description": "Read-only opencode plugin that reports session lifecycle, token usage and waiting permissions/questions to a Telegram bot.",
  "type": "module",
  "main": "monitor.ts",
  "types": "monitor.ts",
  "files": [
    "monitor.ts",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "set:version": "node scripts/set-version.mjs",
    "check": "node scripts/build.mjs",
    "prepublishOnly": "node scripts/build.mjs"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "telegram",
    "notifications",
    "monitor"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/Hipc/opencode-telegram-monitor.git"
  },
  "engines": {
    "node": ">=18"
  }
}
